<?php require_once __DIR__.'/../auth.php'; require_admin(); $result=$conn->query('SELECT * FROM events ORDER BY event_date DESC'); page_start('Practical 12 — Event Management'); ?>
<p>Manage event details and posters. Poster uploads accept JPEG, PNG, or WebP up to 2 MB.</p><p><a class="btn" href="edit.php">Add event</a></p><table><thead><tr><th>Poster</th><th>Event</th><th>Date</th><th>Location</th><th>Actions</th></tr></thead><tbody><?php while($ev=$result->fetch_assoc()):?><tr><td><?php if($ev['poster']):?><img src="uploads/<?=e($ev['poster'])?>" alt="Poster for <?=e($ev['title'])?>" style="max-width:90px;max-height:90px"><?php else:?>—<?php endif;?></td><td><strong><?=e($ev['title'])?></strong><br><?=e($ev['category'])?><br><?=e($ev['description'])?></td><td><?=e($ev['event_date'])?></td><td><?=e($ev['location'])?></td><td><a class="btn" href="edit.php?id=<?=(int)$ev['id']?>">Edit</a><form method="post" action="delete.php" onsubmit="return confirm('Delete event?')"><input type="hidden" name="id" value="<?=(int)$ev['id']?>"><button class="danger">Delete</button></form></td></tr><?php endwhile;?></tbody></table><?php page_end(); ?>
